public static int transformString(String T, List<List<String>> bags) {
    int TLen = T.length();
    int[][] dp = new int[2][TLen + 1];
    Arrays.fill(dp[0], Integer.MAX_VALUE);
    dp[0][0] = 0;

    for (int i = 0; i < bags.size(); i++) {
        Arrays.fill(dp[(i + 1) % 2], Integer.MAX_VALUE);
        for (String S : bags.get(i)) {
            for (int tPos = 0; tPos <= TLen; tPos++) {
                if (dp[i % 2][tPos] < Integer.MAX_VALUE) {
                    dp[(i + 1) % 2][tPos] = Math.min(dp[(i + 1) % 2][tPos], dp[i % 2][tPos]);
                    if (tPos + S.length() <= TLen && T.substring(tPos).startsWith(S)) {
                        dp[(i + 1) % 2][tPos + S.length()] = Math.min(dp[(i + 1) % 2][tPos + S.length()], dp[i % 2][tPos] + 1);
                    }
                }
            }
        }
    }

    return dp[bags.size() % 2][TLen] < Integer.MAX_VALUE ? dp[bags.size() % 2][TLen] : -1;
}
